function getBlogById(id) {
  return blogsDB[id] || null;
}

function getAllBlogs() {
  return Object.values(blogsDB);
}

function getBlogsByCategory(category) {
  return Object.values(blogsDB).filter(function(b) { return b.category === category; });
}

function getBlogsByTag(tag) {
  return Object.values(blogsDB).filter(function(b) { return b.tags.indexOf(tag) !== -1; });
}

function getAllCategories() {
  var cats = {};
  Object.values(blogsDB).forEach(function(b) { cats[b.category] = true; });
  return Object.keys(cats).sort();
}

function getAllTags() {
  var tags = {};
  Object.values(blogsDB).forEach(function(b) {
    b.tags.forEach(function(t) { tags[t] = true; });
  });
  return Object.keys(tags).sort();
}

function getRelatedBlogs(blogId, limit) {
  var blog = getBlogById(blogId);
  if (!blog) return [];
  var related = Object.values(blogsDB).filter(function(b) {
    return b.id !== blogId && b.category === blog.category;
  });
  if (related.length === 0) {
    related = Object.values(blogsDB).filter(function(b) { return b.id !== blogId; });
  }
  return related.slice(0, limit || 4);
}

function getBlogNavigation(blogId) {
  var keys = Object.keys(blogsDB);
  var idx = keys.indexOf(blogId);
  return {
    previous: idx > 0 ? blogsDB[keys[idx - 1]] : null,
    next: idx < keys.length - 1 ? blogsDB[keys[idx + 1]] : null
  };
}
